DrawingAttachment seriesPoint(const DrawingSheetEditor &e,const DrawingEditorModel &model,const DrawingView &view,Vec2 wanted){
 for(const auto &curve:e.curves(view.id))for(auto role:{DrawingPointRole::Start,DrawingPointRole::End,DrawingPointRole::Midpoint}){
  const auto ref=drawingAttachment(view,curve,model.snapshot,role);const auto p=resolveDrawingAttachment(view,model.snapshot,e.curves(view.id),ref);
  if(p.status==DrawingDimensionStatus::Ready&&p.isPoint&&distance(p.point,wanted)<1e-7)return ref;
 }throw std::runtime_error("punto della serie assente");
}
